echo ---MARK---
cd /tmp/pmb && rm -rf polaris-neoforge
echo  | base64 -d | tar xz
echo  | base64 -d > /tmp/pmb/e2e/bot.js
docker run --rm -v /tmp/pmb/polaris-neoforge:/mod -v polaris-mod-gradle:/root/.gradle -w /mod gradle:9.2.1-jdk21 gradle --no-daemon -q build > /tmp/pmb/build.log 2>&1; echo "build exit $?"
cp /tmp/pmb/polaris-neoforge/build/libs/polaris-0.1.0.jar /tmp/pmb/e2e/jar/polaris-neoforge-1.21.4.jar
docker restart pm-stub >/dev/null; docker restart pm-mc >/dev/null
sleep 5; for i in $(seq 1 60); do if docker logs --since 1m pm-mc 2>&1 | grep -q "Done ("; then echo "server up"; break; fi; sleep 5; done
docker logs --since 2m pm-mc 2>&1 | grep -E "Downloaded|Polaris" | tail -5
docker run --rm --network pm-e2e -v /tmp/pmb/e2e:/app -w /app -e MC_HOST=pm-mc node:22-slim node bot.js main 2>&1 | grep -E "PASS|FAIL|RESULT|ERROR"
echo ---DOWN---
docker stop pm-stub >/dev/null
docker run --rm --network pm-e2e -v /tmp/pmb/e2e:/app -w /app -e MC_HOST=pm-mc node:22-slim node bot.js down 2>&1 | grep -E "PASS|FAIL|RESULT|ERROR"
sleep 70; docker logs --since 3m pm-mc 2>&1 | grep -i polaris | tail -5
echo ---BOOT-WITHOUT-POLARIS---
docker restart pm-mc >/dev/null; sleep 40; docker inspect -f "running={{.State.Running}} exit={{.State.ExitCode}}" pm-mc; docker logs --since 1m pm-mc 2>&1 | grep -E "mcopy|ERROR" | tail -3
echo ---SECRETS---
docker logs pm-mc 2>&1 | grep -c -E "secret1|new pass|wrongy1|aaaaaa"
echo ---END---
exit
